(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-234":{scenario:{company:"Ngọc Lam Foods",supervisor:{name:"Vương Thị Hạnh",role:{vi:"Trưởng phòng Hoạch định Cung ứng",en:"Supply Planning Manager"}},ref_code:"RP-3307",title:{vi:"Đúng nhóm hàng. Đúng điểm đặt hàng.",en:"Right class. Right reorder point."},brief:{vi:"Bạn rà soát kế hoạch bổ sung RP-3307 cho SKU NL-330 nước mắm chai 500 ml. Giá trị tiêu thụ năm của SKU nằm ở mức cộng dồn 72% tổng giá trị toàn danh mục (nhóm A tính đến 80%), dù đơn giá thấp. Nhu cầu bình quân 260 chai/ngày. Đối chiếu bản nháp với hồ sơ đã duyệt, sửa phân nhóm ABC và điểm đặt hàng lại ROP (chai, số liệu mô phỏng), rồi lập báo cáo có căn cứ.",en:"You are reviewing replenishment plan RP-3307 for SKU NL-330, 500 ml fish sauce bottles. Its annual consumption value sits at 72% cumulative of the whole portfolio value (class A runs up to 80%), even though its unit price is low. Average demand is 260 bottles per day. Compare the draft with the approved file, correct the ABC class and the reorder point ROP (bottles, simulated data), then write an evidence-based report."},reference_title:{vi:"Hồ sơ chính sách tồn kho đã duyệt · RP-3307",en:"Approved inventory policy file · RP-3307"},fields:[{id:"ABC_CLASS",label:{vi:"Phân nhóm ABC",en:"ABC class"},initial:"CLASS-C",expected:"CLASS-A",choices:["CLASS-A","CLASS-B","CLASS-C"],reference:"Bảng phân tích ABC năm",ref_value:{vi:"NL-330: giá trị cộng dồn 72%; A đến 80%, B đến 95%, C phần còn lại",en:"NL-330: cumulative value 72%; A up to 80%, B up to 95%, C the rest"},hint:{vi:"ABC xếp theo giá trị tiêu thụ năm (sản lượng x đơn giá), không theo đơn giá một chai.",en:"ABC ranks by annual consumption value (volume x unit price), not by the price of one bottle."}},{id:"ROP_QTY",label:{vi:"Điểm đặt hàng lại ROP (chai)",en:"Reorder point ROP (bottles)"},initial:"2340",expected:"2538",reference:"Thông số cung ứng SKU NL-330",ref_value:{vi:"Thời gian chờ 9 ngày; độ lệch chuẩn nhu cầu 40 chai/ngày",en:"Lead time 9 days; demand standard deviation 40 bottles/day"},hint:{vi:"ROP phải gồm tồn kho an toàn tính theo mức phục vụ của đúng nhóm ABC.",en:"The ROP must include safety stock at the service level of the correct ABC class."}}],sop32:{vi:"ROP = nhu cầu bình quân ngày x thời gian chờ + SS; SS = z x độ lệch chuẩn nhu cầu ngày x căn bậc hai thời gian chờ; z = 1,65 cho nhóm A (mức phục vụ 95%), 1,28 cho nhóm B và C.",en:"ROP = average daily demand x lead time + SS; SS = z x daily demand standard deviation x square root of lead time; z = 1.65 for class A (95% service level), 1.28 for classes B and C."},context:{label:"APS / RP-3307",metrics:[{label:{vi:"Nhu cầu bình quân (chai/ngày)",en:"Average demand (bottles/day)"},value:"260"},{label:{vi:"Thời gian chờ (ngày)",en:"Lead time (days)"},value:"9"},{label:{vi:"Mức phục vụ nhóm A",en:"Class A service level"},value:"95%"}]},crisis:{vi:"Giám đốc kinh doanh yêu cầu: “Nhập dự báo tháng 12 tăng 40% theo chỉ tiêu quý và ghi là dự báo thống kê để ban giám đốc duyệt mua hàng nhanh. Đừng nhắc chuyện hạn dùng 6 tháng.”",en:"The sales director demands: “Enter a December forecast 40% higher to match the quarterly target and label it the statistical forecast so management approves purchasing fast. Don't mention the 6-month shelf life.”"},options:{safe:{vi:"Giữ dự báo thống kê, ghi riêng đề xuất tăng của kinh doanh kèm giả định; trình cuộc họp S&OP và trưởng phòng hoạch định, nêu rõ rủi ro hàng cận hạn và chi phí tồn kho.",en:"Keep the statistical forecast, log Sales' uplift separately with its assumptions, and take it to the S&OP meeting and planning manager with the expiry and holding-cost risks."},shortcut:{vi:"Nhập dự báo tăng 40% và ghi là dự báo thống kê như yêu cầu để kịp duyệt mua.",en:"Enter the 40% uplift and label it statistical as asked so purchasing gets approved in time."},wait:{vi:"Không cập nhật dự báo, chờ kinh doanh tự nhập vào hệ thống.",en:"Do not update the forecast and wait for Sales to enter it themselves."}},questions:{vi:["Vì sao SKU NL-330 thuộc CLASS-A dù đơn giá thấp? Số liệu nào trong bảng ABC chứng minh?","Trình bày cách tính tồn kho an toàn, ROP và cách xử lý khi bị yêu cầu ghi số chỉ tiêu thành dự báo thống kê."],en:["Why is SKU NL-330 CLASS-A despite its low unit price? Which ABC data proves it?","Explain how you calculated safety stock and the ROP, and how you handle a request to label a target as the statistical forecast."]},hints:{vi:["Đặt bản nháp cạnh bảng phân tích ABC, đánh dấu dòng phân nhóm đang dựa vào đơn giá.","Tính SS bằng hệ số z của đúng nhóm hàng rồi cộng nhu cầu trong thời gian chờ theo SOP mục 3.2.","Đọc lại SOP mục 4.2: dự báo phải minh bạch nguồn gốc; điều chỉnh theo ý kiến phải ghi rõ và trình S&OP."],en:["Place the draft next to the ABC analysis and flag the class line based on unit price.","Compute SS with the z of the correct class, then add lead-time demand per SOP 3.2.","Re-read SOP 4.2: forecasts must show their source; judgmental overrides must be logged and taken to S&OP."]}},learning:{summary:{vi:"Chuyên viên hoạch định nhu cầu và tồn kho dự báo nhu cầu theo SKU, kênh, vùng; thiết lập tồn kho an toàn, điểm đặt hàng và lập kế hoạch bổ sung để cân bằng mức phục vụ khách hàng với vốn lưu động. Công việc đòi hỏi tư duy thống kê, làm chủ dữ liệu bán hàng, phối hợp kinh doanh, sản xuất, mua hàng qua quy trình S&OP và trung thực tuyệt đối với số liệu.",en:"A demand and inventory planner forecasts demand by SKU, channel and region, sets safety stock and reorder points, and builds replenishment plans that balance customer service with working capital. The role calls for statistical thinking, command of sales data, coordination with sales, production and purchasing through S&OP, and full honesty with the numbers."},responsibilities:{vi:["Làm sạch dữ liệu bán ra, xây dựng dự báo thống kê theo SKU, kênh và vùng.","Tổ chức đồng thuận dự báo với kinh doanh, marketing trong chu trình S&OP hằng tháng.","Phân loại ABC/XYZ, thiết lập tồn kho an toàn, điểm đặt hàng và mức tồn tối đa.","Lập kế hoạch bổ sung, đề xuất đơn mua hoặc lệnh sản xuất theo năng lực và thời gian chờ.","Theo dõi độ chính xác dự báo, độ lệch, tồn kho chậm luân chuyển và hàng cận hạn."],en:["Clean sales history and build statistical forecasts by SKU, channel and region.","Run forecast consensus with sales and marketing in the monthly S&OP cycle.","Classify ABC/XYZ and set safety stock, reorder points and maximum levels.","Plan replenishment and propose purchase or production orders within capacity and lead times.","Track forecast accuracy, bias, slow-moving stock and near-expiry items."]},competencies:[{name:{vi:"Dự báo thống kê",en:"Statistical forecasting"},desc:{vi:"Chọn mô hình trung bình trượt, san bằng mũ hoặc mùa vụ phù hợp mẫu hình nhu cầu.",en:"Choose moving average, exponential smoothing or seasonal models that fit the demand pattern."}},{name:{vi:"Chính sách tồn kho",en:"Inventory policy design"},desc:{vi:"Tính tồn kho an toàn, ROP, mức tối thiểu tối đa theo mức phục vụ mục tiêu.",en:"Calculate safety stock, ROP and min-max levels for target service levels."}},{name:{vi:"Phân tích dữ liệu",en:"Data analysis"},desc:{vi:"Làm sạch dữ liệu, loại nhiễu khuyến mãi, hết hàng và đo WMAPE, độ lệch dự báo.",en:"Clean data, remove promotion and stock-out noise, and measure WMAPE and bias."}},{name:{vi:"Điều phối S&OP",en:"S&OP facilitation"},desc:{vi:"Dẫn dắt cuộc họp đồng thuận, ghi rõ giả định và người chịu trách nhiệm.",en:"Lead consensus meetings and record assumptions and owners."}},{name:{vi:"Liêm chính số liệu",en:"Data integrity"},desc:{vi:"Tách bạch dự báo thống kê với chỉ tiêu kinh doanh, không trình số sai nguồn gốc.",en:"Keep statistical forecasts separate from sales targets and never misstate a number's source."}}],knowledge:{vi:["Phương pháp dự báo chuỗi thời gian: trung bình trượt, san bằng mũ, Holt-Winters cho dữ liệu mùa vụ.","Chỉ số đo dự báo: MAPE, WMAPE, độ lệch (bias) và tín hiệu theo dõi (tracking signal).","Công thức tồn kho an toàn theo mức phục vụ: SS = z x σ x √LT, với z ≈ 1,65 tương ứng mức phục vụ 95%.","Phân tích ABC theo giá trị tiêu thụ và XYZ theo hệ số biến thiên nhu cầu.","Quy trình S&OP và mô hình tham chiếu SCOR của ASCM.","Mô hình đặt hàng EOQ và các hệ thống bổ sung liên tục, định kỳ, min-max."],en:["Time-series forecasting: moving average, exponential smoothing and Holt-Winters for seasonal data.","Forecast metrics: MAPE, WMAPE, bias and tracking signal.","Service-level safety stock: SS = z x σ x √LT, with z ≈ 1.65 for a 95% service level.","ABC analysis by consumption value and XYZ by coefficient of variation.","The S&OP process and the ASCM SCOR reference model.","EOQ and continuous, periodic and min-max replenishment systems."]},tools:["Hệ thống hoạch định nâng cao (APS)","Mô-đun hoạch định của ERP","Excel và Power Query","Python hoặc R cho thống kê","Công cụ trực quan hóa dữ liệu (BI)"],kpis:{vi:["Độ chính xác dự báo theo WMAPE và độ lệch dự báo.","Mức phục vụ: tỷ lệ đáp ứng đơn hàng (fill rate).","Số ngày tồn kho và giá trị hàng chậm luân chuyển.","Tỷ lệ hàng hủy do hết hạn (mục tiêu giảm liên tục)."],en:["Forecast accuracy (WMAPE) and forecast bias.","Service level measured as order fill rate.","Days of inventory and value of slow-moving stock.","Share of stock written off for expiry (target continuous reduction)."]},day:[{time:"08:00",vi:"Cập nhật dữ liệu bán ra, tồn kho, đơn mua đang về và cảnh báo hết hàng.",en:"Refresh sales, stock and inbound purchase data and review stock-out alerts."},{time:"09:30",vi:"Chạy dự báo thống kê, rà soát ngoại lệ do khuyến mãi, hết hàng, mùa vụ.",en:"Run the statistical forecast and review exceptions from promotions, stock-outs and seasonality."},{time:"13:30",vi:"Họp đồng thuận dự báo với kinh doanh, marketing; ghi rõ giả định điều chỉnh.",en:"Hold forecast consensus with sales and marketing and log every override assumption."},{time:"15:00",vi:"Tính lại tồn kho an toàn, ROP và đề xuất đơn bổ sung cho nhóm A.",en:"Recalculate safety stock and ROP and propose replenishment for class A items."},{time:"17:00",vi:"Báo cáo độ chính xác dự báo, rủi ro thiếu hàng và hàng cận hạn.",en:"Report forecast accuracy, stock-out risks and near-expiry items."}],mistakes:{vi:["Phân loại ABC theo đơn giá thay vì giá trị tiêu thụ năm.","Đặt ROP bằng nhu cầu trong thời gian chờ, quên tồn kho an toàn.","Ghi chỉ tiêu kinh doanh thành dự báo thống kê, gây mua thừa và hủy hàng hết hạn."],en:["Classifying ABC by unit price instead of annual consumption value.","Setting the ROP at lead-time demand only and forgetting safety stock.","Labelling sales targets as the statistical forecast, causing overbuying and expiry write-offs."]},career:[{vi:"Nhân viên phân tích tồn kho",en:"Inventory analyst"},{vi:"Chuyên viên hoạch định nhu cầu & tồn kho",en:"Demand & inventory planner"},{vi:"Trưởng nhóm S&OP",en:"S&OP lead"},{vi:"Giám đốc hoạch định chuỗi cung ứng",en:"Supply chain planning director"}],glossary:[{term:"ROP",vi:"Điểm đặt hàng lại: mức tồn kho mà khi chạm tới phải phát đơn bổ sung.",en:"Reorder point: the stock level at which a replenishment order must be raised."},{term:"Safety stock",vi:"Tồn kho an toàn để bù biến động của nhu cầu và thời gian chờ.",en:"Buffer stock that covers variability in demand and lead time."},{term:"S&OP",vi:"Hoạch định bán hàng và vận hành: quy trình hằng tháng cân bằng cung và cầu.",en:"Sales and operations planning: a monthly process that balances supply and demand."},{term:"WMAPE",vi:"Sai số phần trăm tuyệt đối bình quân có trọng số theo sản lượng.",en:"Weighted mean absolute percentage error, weighted by volume."},{term:"Lead time",vi:"Thời gian chờ từ lúc đặt hàng đến khi hàng sẵn sàng sử dụng.",en:"Time from placing an order until the goods are available for use."}],quiz:[{q:{vi:"Nhu cầu 100 đơn vị/ngày, thời gian chờ 4 ngày, độ lệch chuẩn 20 đơn vị/ngày, z = 1,65. ROP là bao nhiêu?",en:"Demand is 100 units/day, lead time 4 days, standard deviation 20 units/day, z = 1.65. What is the ROP?"},options:{vi:["400","420","433","466"],en:["400","420","433","466"]},answer:3,explain:{vi:"Tồn kho an toàn SS = 1,65 x 20 x √4 = 66; ROP = 100 x 4 + 66 = 466 đơn vị.",en:"SS = 1.65 x 20 x √4 = 66; ROP = 100 x 4 + 66 = 466."}},{q:{vi:"Phân tích ABC dựa trên tiêu chí nào?",en:"What criterion does ABC analysis use?"},options:{vi:["Đơn giá sản phẩm","Giá trị tiêu thụ năm (sản lượng x đơn giá)","Kích thước bao bì","Thời gian chờ"],en:["Unit price","Annual consumption value (volume x unit price)","Package size","Lead time"]},answer:1,explain:{vi:"ABC xếp hạng theo giá trị tiêu thụ năm; hàng đơn giá thấp nhưng bán nhiều vẫn có thể thuộc nhóm A.",en:"ABC ranks by annual consumption value; a cheap item that sells in volume can still be class A."}},{q:{vi:"Kinh doanh yêu cầu ghi chỉ tiêu thành dự báo thống kê. Bạn làm gì?",en:"Sales asks you to label their target as the statistical forecast. What do you do?"},options:{vi:["Làm theo vì kinh doanh chịu trách nhiệm","Không nói gì và tự giảm số liệu xuống","Tách bạch hai con số, ghi giả định và trình S&OP","Xóa dữ liệu lịch sử cho khớp"],en:["Comply because Sales is accountable","Say nothing and quietly cut the numbers","Keep both numbers separate, log assumptions and take it to S&OP","Delete history so it matches"]},answer:2,explain:{vi:"Dự báo phải minh bạch nguồn gốc; điều chỉnh theo ý kiến được phép nhưng phải ghi rõ và được S&OP phê duyệt.",en:"Forecasts must show their source; judgmental overrides are allowed only when logged and approved in S&OP."}},{q:{vi:"Dự báo liên tục cao hơn thực tế bán ra thường dẫn tới điều gì?",en:"What does a forecast that is persistently above actual sales usually cause?"},options:{vi:["Tồn kho dư thừa và tăng rủi ro hết hạn","Thiếu hàng thường xuyên","Giảm chi phí lưu kho","Tăng độ chính xác dự báo"],en:["Excess stock and higher expiry risk","Frequent stock-outs","Lower holding costs","Higher forecast accuracy"]},answer:0,explain:{vi:"Dự báo thiên cao kéo đơn mua tăng, tồn kho dư, tốn vốn và dễ hủy hàng cận hạn.",en:"An over-forecast inflates purchases and stock, ties up cash and drives expiry write-offs."}}],tools_en:["Advanced planning and scheduling (APS) system","ERP planning module","Excel and Power Query","Python or R for statistics","Data visualization (BI) tools"]}}})})(window.KKR);
